local key = "obfuscate"
local hex = ""
local function hex2s(s)
    local t = {}
    for i = 1, #s, 2 do
        t[#t+1] = string.char(tonumber(s:sub(i, i+1), 16))
    end
    return table.concat(t)
end
local function xordec(s, k)
    local r = ""
    for i = 1, #s do
        r = r .. string.char(string.byte(s, i) ~ string.byte(k, (i-1) % #k + 1))
    end
    return r
end
local decoded = xordec(hex2s(hex), key)
local fn = loadstring(decoded)
if fn then fn() else error("Load failed") end
